package com.ryanjei.orushio.pve.economy;
import static org.junit.jupiter.api.Assertions.*;import com.ryanjei.orushio.pve.map.*;import com.ryanjei.orushio.pve.persistence.RepositoryException;import java.nio.file.*;import java.time.Duration;import java.util.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;
class YamlGameplaySettingsRepositoryTest{@TempDir Path temp;@Test void stableIdと全設定をAtomic保存して再読込する(){var repository=new YamlGameplaySettingsRepository(temp);GameplaySettings value=new GameplaySettings(List.of(new GameplaySettings.ResourceZone(UUID.randomUUID(),PointCategory.MINING,"IRON_ORE",4,Duration.ofSeconds(30),new Cuboid(0,0,0,2,2,2))),List.of(new GameplaySettings.Shop(UUID.randomUUID(),new BlockPoint(1,2,3,0,0),"SWORD",List.of(new GameplaySettings.Product(0,PointCategory.MINING,5,new ItemSpec("WOODEN_SWORD",1,Map.of("minecraft:sharpness",1),true))))));repository.save("map-a",value);assertEquals(value,repository.load("map-a"));repository.save("map-a",value);assertTrue(Files.exists(temp.resolve("map-a/gameplay-settings.yml.bak")));}@Test void 未設定Mapは空でunknownSchemaを拒否する()throws Exception{var repository=new YamlGameplaySettingsRepository(temp);assertEquals(GameplaySettings.empty(),repository.load("map-a"));Path path=temp.resolve("map-a/gameplay-settings.yml");Files.createDirectories(path.getParent());Files.writeString(path,"schemaVersion: \"99\"\n");assertThrows(RepositoryException.class,()->repository.load("map-a"));}}
